 for r in [('Phyrr','菲尔','暂定·沿原稿','英文对照','942','死亡世界兼刑罚世界'),('Port Maw Subsector','巨口港次星区','暂定·沿现稿词根','英文对照','943','统一地理层级'),('Æstellica','埃斯特利卡','暂定·沿原稿','英文对照','943','巨口港环绕的行星'),('Nexus System','枢纽系统','暂定·语境分义','英文对照','943 B0020','海军设施名称，不按恒星系处理'),('Officio Astra','星界署','暂定·修正机构义','英文对照','943 B0030','区别 Ordo Astra 星界审判庭'),('Grand Admiral','海军元帅','暂定·沿778同人职衔','英文对照','943 B0039/B0054','奥菲斯·拉布雷的海军职衔'),('The Lexicus Planetarium','星表典籍','暂定·沿原稿','英文对照','943 B0036','书名正文加书名号')]:f.write('\t'.join(r)+'\n')
